// Returns the embedded cfg bytes for a language code ("en","ru",...) or nullptr; sets size.
const char* embedded_text(const std::string& code, std::size_t& size) {
    for (const auto& e : kEmbTexts)
        if (code == e.code) { size = e.size; return reinterpret_cast<const char*>(e.data); }
    size = 0;
    return nullptr;
}

